import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { FaEnvelope, FaLock } from 'react-icons/fa';
import logo from '../GI_logo.png';
import './Auth.css';

const SignIn = () => {
  const [showPassword, setShowPassword] = useState(false);
  const [form, setForm] = useState({ email: '', password: '' });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async e => {
    e.preventDefault();
    setError(null);
    setLoading(true);
    try {
      const res = await fetch('http://localhost:5000/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form)
      });
      const data = await res.json();
      if (res.ok) {
        localStorage.setItem('token', data.token);
        // Optionally store user info: localStorage.setItem('user', JSON.stringify(data.user));
        navigate('/'); // Redirect to home or dashboard
      } else {
        setError(data.message || 'Login failed');
      }
    } catch (err) {
      setError('Network error');
    }
    setLoading(false);
  };

  return (
    <div className="auth-bg">
      <div className="auth-container">
        <img src={logo} alt="Global Image Logo" className="auth-logo-img" />
        <h2>Sign In</h2>
        <div className="auth-tagline">Welcome back! Please sign in to your account.</div>
        {error && <div style={{color: 'red', marginBottom: '1rem'}}>{error}</div>}
        <form className="auth-form" onSubmit={handleSubmit}>
          <div className="auth-input-wrapper">
            <span className="auth-input-icon"><FaEnvelope /></span>
            <input type="email" id="email" name="email" placeholder="Email" required value={form.email} onChange={handleChange} />
          </div>
          <div className="auth-input-wrapper">
            <span className="auth-input-icon"><FaLock /></span>
            <input type={showPassword ? 'text' : 'password'} id="password" name="password" placeholder="Password" required value={form.password} onChange={handleChange} />
            <button type="button" className="toggle-password" onClick={() => setShowPassword(s => !s)}>{showPassword ? '🙈' : '👁️'}</button>
          </div>
          <button type="submit" disabled={loading}>{loading ? 'Signing in...' : 'Sign In'}</button>
        </form>
        <div className="auth-links">
          <Link to="/register">Create account</Link>
          <Link to="#">Forgot password?</Link>
        </div>
      </div>
    </div>
  );
};

export default SignIn;
